///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(panel_Top);
        $c.bns.BnsPanelToGroupBox(panel_1);

        // 현재일자 기준 직전 영업일 가져오기
        // fn_get_AgBzDd(dts_Date, cGetToday("yyyymmdd"));

        // 직전영업일을 기본 세팅
        // edt_FromDt.text = dts_Date.NameString(1, "CALND_DD");
        // edt_ToDt.text   = dts_Date.NameString(1, "CALND_DD");
        edt_FromDt.setValue($c.ut.cGetToday("yyyymmdd"));

        // 디자인 가리기
        label_3.hide();
        edt_ToDt.hide();
        btn_EDate.hide();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24100.onpageload" });
    }
};

