///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description FRN금리정보조회(코스콤)
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let param = "";
    param += "&{P}V_ISUR_CD=" + txb_IsurCd.getValue(); // 발행기관코드
    param += "&{P}V_ISUR_NM=" + txb_IsurNm.getValue(); // 발행기관명
    param += "&{P}V_STD_CD=" + txb_StdCd.getValue(); // 표준코드
    param += "&{P}V_ISU_NM=" + txb_IsuNm.getValue(); // 종목명
    param += "&{P}V_FROM_DT=" + edt_FromDt.getValue(); // From Date
    param += "&{P}V_TO_DT=" + edt_ToDt.getValue(); // To Date
    param += "&{P}V_LIST_STAT_CD=" + cmb_ListStatCd.getValue(); // 상장상태

    let dsNm = 'BNS_BND_FRN_INT_INFO_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectBndFrnIntInfoList';
    $c.bns.fn_SearchBns("ULDBNS24100.xml", dts_List1, dsNm, qryId, param);
};

/**
 * @method
 * @name search1
 * @description FRN금리정보 이력(추이)조회
 * @returns {void}
 * @hidden N
 */
scwin.search1 = function() {
    let param = "";
    param += "&{P}V_STD_CD=" + dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD"); // 표준코드

    let dsNm = 'BNS_FRN_INT_DRFT_RCV_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectBndFrnIntDrftRcvList';
    $c.bns.fn_SearchBns("ULDBNS24100.xml", dts_List2, dsNm, qryId, param);
};

/**
 * @method
 * @name showIsuPopup
 * @description 종목 팝업 오픈
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.showIsuPopup = function(obj) {
    scwin.fn_GetPar = scwin.getParListBndIsu;
    scwin.fn_SetPar = scwin.setParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(obj);
};

/**
 * @method
 * @name getParListBndIsu
 * @description 상장종목 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: txb_IsurCd.getValue(),
        ISU_NM: txb_IsuNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParListBndIsu
 * @description 상장종목 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParListBndIsu = function(arrPar) {
    txb_StdCd.setValue(arrPar[0].STD_CD);
    txb_IsuNm.setValue(arrPar[0].ISU_NM);
};

/**
 * @method
 * @name showIsurPopup
 * @description 발행기관 팝업을 보여준다.
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.showIsurPopup = function(obj) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(obj);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: txb_IsurCd.getValue(),
        ISUR_NM: txb_IsurNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].ISUR_NM);
};

/**
 * @method
 * @name downExcel
 * @description 엑셀 다운로드
 * @returns {void}
 * @hidden N
 */
scwin.downExcel = function() {
    let file_path = "";
    const today = $c.ut.cGetToday("yyyymmddhhmmss");
    file_path = $c.session.getExcelDownPath() + "FRN금리_" + today + ".xlsx";
    $c.data.downloadGridViewOffice(grd_List1, "sheet1", file_path, 8, 0);
};
